package uy.utu.biblioteca;
import java.sql.*;import java.util.*;import org.mindrot.jbcrypt.BCrypt;
public class UsuarioDAO {
 public void asegurarAdministradorInicial()throws SQLException{try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM usuarios");ResultSet r=p.executeQuery()){r.next();if(r.getInt(1)==0){String inicial=System.getenv("APP_ADMIN_PASSWORD");if(inicial==null||inicial.length()<8)throw new SQLException("Definí APP_ADMIN_PASSWORD (mínimo 8 caracteres) para crear el administrador inicial.");try(PreparedStatement i=c.prepareStatement("INSERT INTO usuarios(nombre,documento,email,username,password_hash,rol) VALUES(?,?,?,?,?,'ADMIN')")){i.setString(1,"Administrador");i.setString(2,"00000000");i.setString(3,"admin@biblioteca.local");i.setString(4,"admin");i.setString(5,BCrypt.hashpw(inicial,BCrypt.gensalt(12)));i.executeUpdate();}}}}
 public Usuario autenticar(String user,String password)throws SQLException{String q="SELECT * FROM usuarios WHERE username=? AND activo=TRUE";try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement(q)){p.setString(1,user);try(ResultSet r=p.executeQuery()){if(r.next()&&BCrypt.checkpw(password,r.getString("password_hash")))return map(r);}}return null;}
 public List<Usuario> listar()throws SQLException{List<Usuario> l=new ArrayList<>();try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement("SELECT * FROM usuarios ORDER BY nombre");ResultSet r=p.executeQuery()){while(r.next())l.add(map(r));}return l;}
 public void crear(String nombre,String doc,String email,String user,String pass,String rol)throws SQLException{String q="INSERT INTO usuarios(nombre,documento,email,username,password_hash,rol) VALUES(?,?,?,?,?,?)";try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement(q)){p.setString(1,nombre);p.setString(2,doc);p.setString(3,email);p.setString(4,user);p.setString(5,BCrypt.hashpw(pass,BCrypt.gensalt(12)));p.setString(6,rol);p.executeUpdate();}}
 public void cambiarEstado(int id,boolean activo)throws SQLException{try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement("UPDATE usuarios SET activo=? WHERE id=?")){p.setBoolean(1,activo);p.setInt(2,id);p.executeUpdate();}}
 private Usuario map(ResultSet r)throws SQLException{return new Usuario(r.getInt("id"),r.getString("nombre"),r.getString("documento"),r.getString("email"),r.getString("username"),r.getString("rol"),r.getBoolean("activo"));}
}
